const input = $input.first().json;
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : input;
const required = ['application_id', 'dealer_name', 'full_name', 'email'];
const missing = required.filter(f => !body[f]);

if (missing.length) return [{ json: { ok: false, missing } }];

return [{
  json: {
    ok: true,
    application_id: body.application_id,
    dealer_name:    body.dealer_name,
    full_name:      body.full_name,
    email:          body.email,
    phone:          body.phone || null,
    booking_url:    body.booking_url || null,
    admin_url:      body.admin_url || ''
  }
}];

const legalFooter = `<div style="margin-top:24px;padding-top:14px;border-top:1px solid #ddd;font-size:11px;color:#777;line-height:1.5">Black Label Market es una marca de <strong>KAZAWEB, S.L.U.</strong> (NIF B42761254), con domicilio en Lugar Rebordelo nº 35, Planta 2, 15930 Boiro, A Coruña. Inscrita en el Registro Mercantil de Santiago de Compostela, Tomo 395, Folio 51, Hoja SC-51053.<br>Puedes solicitar la baja de comunicaciones o ejercer tus derechos de privacidad escribiendo a <a href="mailto:privacidad@blacklabelmarket.es">privacidad@blacklabelmarket.es</a>. Consulta nuestra <a href="https://blacklabelmarket.es/legal/privacidad">Política de Privacidad</a>.</div>`;

const d = $input.first().json;
const MAIL_FROM = $env.MAIL_FROM || 'Black Label Market <no-reply@blacklabelmarket.es>';

const callToAction = d.booking_url
  ? `<p><a href="${d.booking_url}">Reservar la llamada</a></p>`
  : `<p>Respondednos a este email y os proponemos horario directamente.</p>`;

const emailHtml = `<p>Hola ${d.full_name},</p>
<p><strong>${d.dealer_name}</strong> encaja con los criterios de Black Label Market.</p>
<p>El siguiente paso es una llamada breve en la que os explicamos cómo funciona la plataforma, resolvemos precio y condiciones, y dejamos cerrados los detalles del alta. Elegid vosotros el hueco que mejor os venga:</p>
${callToAction}
<p>Un saludo,<br>Black Label Market</p>`;

return [{
  json: {
    ...d,
    emailPayload: {
      from: MAIL_FROM, to: [d.email],
      subject: 'El siguiente paso: agenda tu llamada',
      html: emailHtml + legalFooter
    }
  }
}];
